fn flipud(m: Vec<f32>) -> Vec<f32> {
    // `Vec<T>::into_iter()` for Vec<f32> yields an iterator of f32,
    // which implements DoubleEndedIterator, so we can call `.rev()`
    // to traverse the elements in reverse order, and then collect
    // them into a new Vec<f32>.
    m.into_iter().rev().collect()
}

